create extension if not exists pgcrypto;
create table if not exists public.sov_runs(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),status text not null check(status in('running','completed','failed')),market text not null default 'both' check(market in('both','ru','en')),prompt_count integer not null default 0,successful_count integer not null default 0,failed_count integer not null default 0,duration_ms integer,error text);
create table if not exists public.sov_results(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.sov_runs(id) on delete cascade,created_at timestamptz not null default now(),prompt_id text not null,locale text not null check(locale in('ru','en')),category text not null,provider text not null check(provider in('chatgpt','claude','perplexity')),model text,prompt text not null,answer text not null default '',citations jsonb not null default '[]',brands jsonb not null default '[]',position_order jsonb not null default '[]',latency_ms integer,status text not null check(status in('success','error')),error text);
create index if not exists sov_runs_created_idx on public.sov_runs(created_at desc);create index if not exists sov_results_run_idx on public.sov_results(run_id);create index if not exists sov_results_provider_locale_idx on public.sov_results(provider,locale);
alter table public.sov_runs enable row level security;alter table public.sov_results enable row level security;
-- Do not add anon/authenticated policies. Vercel only uses the service role key.